function advanceNpcQuest(catches){const quest=ensureNpcQuest(),caught=catches.filter(f=>f.name===quest.fish&&f.weight>=quest.weight).length;if(!caught)return;quest.progress+=caught;if(quest.progress<quest.target)return;const reward=quest.reward,bait=baitTypes.find(item=>item.id===reward.bait);state.coins+=reward.coins;state.total+=reward.coins;state.xp+=50;state.reputation+=reward.reputation;state.localReputation[state.location]=localRep(state.location)+reward.reputation;state.baitStock[reward.bait]=(state.baitStock[reward.bait]||0)+reward.amount;state.completedQuests++;const reelAward=!state.questReel&&state.completedQuests>=5;if(reelAward)state.questReel=true;state.journal.unshift(`Задание NPC выполнено: +${reward.coins} ◉, +${reward.reputation} репутации${reelAward?', получена катушка инспектора':''}.`);state.npcQuest=makeNpcQuest();note(`Задание инспектора выполнено! +${reward.coins} ◉ · ${bait.name} ×${reward.amount}${reelAward?' · Катушка инспектора':''}`) }
function setTechnique(key){if(!techniques[key])return;state.technique=key;state.journal.unshift(`Выбрана техника: ${techniques[key].name}.`);note(`Техника: ${techniques[key].name}. ${techniques[key].desc}`);render()}
function renderWorld(){const weather=weatherData[world.weather],timeOfDay=timeData[world.time],season=seasons[world.season],event=eventData[world.event],technique=activeTechnique(),quest=ensureNpcQuest(),market=dailyMarket(),bait=baitTypes.find(item=>item.id===quest.reward.bait),available=activePool().map(fish=>fish.name);$('weatherStatus').textContent=`${weather.icon} ${weather.name}`;$('timeStatus').textContent=`${season.icon} ${season.name} · ${timeOfDay.name}`;$('eventStatus').textContent=event.name;$('worldSummary').innerHTML=`<article><b>${weather.icon} ${weather.name} · ${season.icon} ${season.name}</b><small>Активность: ${Math.round(worldActivity()*100)}% · доступно видов: ${available.length}</small></article><article><b>${event.name}</b><small>Погода, время и сезон изменяют улов. Сейчас: ${available.join(' · ')}.</small></article><article><b>★ Репутация: ${state.reputation} · местная: ${localRep(state.location)}</b><small>Новые локации требуют уровень и репутацию; торговец открывается с 10 местной репутации.</small></article>`;$('techniqueGrid').innerHTML=Object.entries(techniques).map(([key,t])=>`<button class="technique-card ${state.technique===key?'active':''}" onclick="setTechnique('${key}')"><b>${t.icon} ${t.name}</b><small>${t.desc}</small></button>`).join('');$('questContent').innerHTML=`<b>👩‍✈️ ${quest.npc}</b><p>Поймать ${quest.target} × ${quest.fish} весом от ${quest.weight} кг.</p><div class="quest-meter"><i style="width:${quest.progress/quest.target*100}%"></i></div><small>${quest.progress} / ${quest.target} · ${quest.reward.coins} ◉ · +${quest.reward.reputation} репутации · ${bait.name} ×${quest.reward.amount}</small>`;if($('marketContent'))$('marketContent').innerHTML=`<b>📈 Заказ на сегодня: ${market.fish}</b><p>Рынок платит на ${Math.round(market.bonus*100)}% больше за этот вид.</p>`}
function syncWorld(){const weather=Object.keys(weatherData),times=Object.keys(timeData),events=Object.keys(eventData),seasonKeys=Object.keys(seasons),phase=Math.floor(session/20);world={weather:weather[phase%weather.length],time:times[Math.floor(session/40)%times.length],event:events[Math.floor(session/60)%events.length],season:seasonKeys[Math.floor(session/90)%seasonKeys.length]};$('game').className=`game location-${state.location} time-${world.time} weather-${world.weather} season-${world.season}`;$('weatherFx').className=`weather-fx weather-${world.weather}`;renderWorld()}
function setTension(load=0){const {rod,line,limit}=tackleLimits(),ratio=Math.min(1,load/limit),bar=$('tensionBar');$('tensionValue').textContent=`${load.toFixed(1)} кг · л.${line} / уд.${rod}`;bar.style.width=(ratio*100)+'%';bar.style.background=ratio>.82?'#ff6e60':ratio>.6?'#ffe067':'#58e5d0';$('equippedRod').classList.toggle('strained',ratio>.82);sceneRenderer.tension=ratio*100;return ratio}
